export interface ConnectorConfig {
  githubToken: string
  githubOwner: string
  githubRepo: string
  zendeskToken: string
  zendeskSubdomain: string
  fetch?: typeof fetch
}

export interface ZendeskTicketCreatedPayload {
  detail: {
    id: string
    subject: string
    description: string
  }
}

export interface HandleResult {
  githubIssueNumber: number
  githubIssueUrl: string
  zendeskCommentId: number
}

async function postJson<T>(
  url: string,
  body: unknown,
  token: string,
  fetchFn: typeof fetch,
): Promise<T> {
  const response = await fetchFn(url, {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${token}`,
      Accept: 'application/vnd.github.v3+json',
      'Content-Type': 'application/json',
    },
    body: JSON.stringify(body),
  })

  if (!response.ok) {
    throw new Error(`POST ${url} failed with ${response.status} ${response.statusText}`)
  }

  return response.json() as Promise<T>
}

async function postZendeskComment(
  url: string,
  body: unknown,
  token: string,
  fetchFn: typeof fetch,
): Promise<{ comment: { id: number } }> {
  const response = await fetchFn(url, {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${token}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify(body),
  })

  if (!response.ok) {
    throw new Error(`POST ${url} failed with ${response.status} ${response.statusText}`)
  }

  return response.json() as Promise<{ comment: { id: number } }>
}

export async function handle(
  payload: ZendeskTicketCreatedPayload,
  config: ConnectorConfig,
): Promise<HandleResult> {
  const fetchFn = config.fetch ?? fetch

  if (!payload.detail?.id) {
    throw new Error('Missing required field: detail.id')
  }
  if (!payload.detail?.subject) {
    throw new Error('Missing required field: detail.subject')
  }
  if (!payload.detail?.description) {
    throw new Error('Missing required field: detail.description')
  }

  const { id: ticketId, subject, description } = payload.detail

  const githubIssueUrl = `https://api.github.com/repos/${config.githubOwner}/${config.githubRepo}/issues`
  const githubResponse = await postJson<{ number: number; html_url: string }>(
    githubIssueUrl,
    { title: subject, body: description },
    config.githubToken,
    fetchFn,
  )

  const commentBody = `GitHub issue created: ${githubResponse.html_url}`
  const zendeskCommentUrl = `https://${config.zendeskSubdomain}.zendesk.com/api/v2/tickets/${ticketId}/comments.json`
  const zendeskResponse = await postZendeskComment(
    zendeskCommentUrl,
    { comment: { body: commentBody } },
    config.zendeskToken,
    fetchFn,
  )

  return {
    githubIssueNumber: githubResponse.number,
    githubIssueUrl: githubResponse.html_url,
    zendeskCommentId: zendeskResponse.comment.id,
  }
}

