describe('handle', () => {
  let baseConfig: ConnectorConfig
  let calls: RecordedCall[]

  beforeEach(() => {
    baseConfig = {
      githubToken: 'gh-test-token',
      githubOwner: 'octocat',
      githubRepo: 'Hello-World',
      zendeskToken: 'zd-test-token',
      zendeskSubdomain: 'example',
    }
    calls = []
  })

  function makeFetch(handler: (req: RecordedCall) => Response) {
    const { fetch, calls: recordedCalls } = fakeFetch(handler)
    calls.push(...recordedCalls)
    return fetch
  }

  it('creates GitHub issue and posts Zendesk comment on happy path', async () => {
    const fetch = makeFetch((req) => {
      if (req.url.includes('/repos/octocat/Hello-World/issues')) {
        return jsonResponse({ number: 42, html_url: 'https://github.com/octocat/Hello-World/issues/42' }, 201)
      }
      if (req.url.includes('/tickets/14038/comments.json')) {
        return jsonResponse({ comment: { id: 999, body: 'GitHub issue created: https://github.com/octocat/Hello-World/issues/42', author_id: 1 } }, 201)
      }
      return jsonResponse({ error: 'not found' }, 404)
    })

    const payload: ZendeskTicketCreatedPayload = {
      detail: {
        id: '14038',
        subject: 'Test ticket',
        description: 'Test description',
      },
    }

    const result = await handle(payload, { ...baseConfig, fetch })

    expect(result.githubIssueNumber).toBe(42)
    expect(result.githubIssueUrl).toBe('https://github.com/octocat/Hello-World/issues/42')
    expect(result.zendeskCommentId).toBe(999)
    expect(calls.length).toBe(2)

    const githubCall = calls[0]
    expect(githubCall.method).toBe('POST')
    expect(githubCall.url).toBe('https://api.github.com/repos/octocat/Hello-World/issues')
    expect(githubCall.json).toEqual({ title: 'Test ticket', body: 'Test description' })
    expect(githubCall.headers.get('authorization')).toBe('Bearer gh-test-token')
    expect(githubCall.headers.get('accept')).toBe('application/vnd.github.v3+json')

    const zendeskCall = calls[1]
    expect(zendeskCall.method).toBe('POST')
    expect(zendeskCall.url).toBe('https://example.zendesk.com/api/v2/tickets/14038/comments.json')
    expect(zendeskCall.json).toEqual({ comment: { body: 'GitHub issue created: https://github.com/octocat/Hello-World/issues/42' } })
    expect(zendeskCall.headers.get('authorization')).toBe('Bearer zd-test-token')
  })

  it('throws when detail.id is missing', async () => {
    const fetch = makeFetch(() => jsonResponse({}, 200))
    const payload = { detail: { subject: 'x', description: 'y' } } as ZendeskTicketCreatedPayload

    await expect(handle(payload, { ...baseConfig, fetch })).rejects.toThrow('Missing required field: detail.id')
  })

  it('throws when detail.subject is missing', async () => {
    const fetch = makeFetch(() => jsonResponse({}, 200))
    const payload = { detail: { id: '1', description: 'y' } } as ZendeskTicketCreatedPayload

    await expect(handle(payload, { ...baseConfig, fetch })).rejects.toThrow('Missing required field: detail.subject')
  })

  it('throws when detail.description is missing', async () => {
    const fetch = makeFetch(() => jsonResponse({}, 200))
    const payload = { detail: { id: '1', subject: 'x' } } as ZendeskTicketCreatedPayload

    await expect(handle(payload, { ...baseConfig, fetch })).rejects.toThrow('Missing required field: detail.description')
  })

  it('throws with status and endpoint when GitHub API returns non-2xx', async () => {
    const fetch = makeFetch(() => jsonResponse({ message: 'Bad credentials' }, 401))
    const payload: ZendeskTicketCreatedPayload = {
      detail: { id: '1', subject: 'Test', description: 'Desc' },
    }

    await expect(handle(payload, { ...baseConfig, fetch })).rejects.toThrow(
      'POST https://api.github.com/repos/octocat/Hello-World/issues failed with 401 Unauthorized',
    )
  })

  it('throws with status and endpoint when Zendesk API returns non-2xx', async () => {
    const fetch = makeFetch((req) => {
      if (req.url.includes('/repos/octocat/Hello-World/issues')) {
        return jsonResponse({ number: 1, html_url: 'https://github.com/octocat/Hello-World/issues/1' }, 201)
      }
      return jsonResponse({ error: 'Forbidden' }, 403)
    })
    const payload: ZendeskTicketCreatedPayload = {
      detail: { id: '1', subject: 'Test', description: 'Desc' },
    }

    await expect(handle(payload, { ...baseConfig, fetch })).rejects.toThrow(
      'POST https://example.zendesk.com/api/v2/tickets/1/comments.json failed with 403 Forbidden',
    )
  })
})

